from pathlib import Path
import hashlib, json, shutil, subprocess
root=Path.cwd()
out=root/"reports/T0006/review-r2-freeze"
frozen=out/"input-snapshot"
targets=["src/kmesh/logic/proof.py","tests/test_proof.py","README.md","docs/implementation_status.md","docs/handoffs/T0006-proof-verifier.md","docs/decisions.md","reports/T0006/provenance.md","reports/T0006/pi-r2-full/provenance.md","reports/T0006/mutation_set_check_r2.py","reports/T0006/record_check.py"]
hashes={}
for name in targets:
    src=root/name
    dst=frozen/name
    dst.parent.mkdir(parents=True,exist_ok=True)
    shutil.copyfile(src,dst)
    hashes[name]=hashlib.sha256(src.read_bytes()).hexdigest()
assert hashes["src/kmesh/logic/proof.py"]=="008bdd3633a5d2327cd711b7c9de7149df86b588632db659a23bf34207963daa"
assert hashes["tests/test_proof.py"]=="21e099b8939e35f90e188062973d0b5e553e07e50f86127441d399a8848897c3"
previous=json.loads((root/"reports/T0006/review-r1-freeze/audit.json").read_text())
original_prov=(root/"reports/T0006/review-r1-freeze/input-snapshot/reports/T0006/provenance.md").read_bytes()
assert (root/"reports/T0006/provenance.md").read_bytes().startswith(original_prov)
old_changes=[]
for name,digest in previous["history_sha256"].items():
    if hashlib.sha256((root/name).read_bytes()).hexdigest()!=digest:
        old_changes.append(name)
assert old_changes==["reports/T0006/provenance.md"],old_changes
previous_review=json.loads((root/"reports/T0006/review-r1/final-audit.json").read_text())
for name,digest in previous_review["review_artifacts_sha256"].items():
    if name.startswith("reports/"):
        assert hashlib.sha256((root/name).read_bytes()).hexdigest()==digest,name
history={}
for task in range(1,7):
    for p in (root/f"reports/T{task:04d}").rglob("*"):
        if not p.is_file() or "pytest-tmp" in p.parts or "__pycache__" in p.parts:
            continue
        if task==6 and any(part.startswith("review-r2") for part in p.parts):
            continue
        history[str(p.relative_to(root))]=hashlib.sha256(p.read_bytes()).hexdigest()
records=[]
for p in sorted((root/"reports/T0006").glob("pi-r2*/record.json")):
    d=json.loads(p.read_text())
    assert d["before"]["source_sha256"]==d["after"]["source_sha256"],p
    assert d["before"]["source_sha256"]["src/kmesh/logic/proof.py"]==hashes["src/kmesh/logic/proof.py"],p
    for stream in ("stdout","stderr"):
        assert hashlib.sha256((p.parent/(stream+".txt")).read_bytes()).hexdigest()==d[stream+"_sha256"],p
    records.append({"run":p.parent.name,"exit_code":d["exit_code"],"elapsed_s":d["elapsed_s"],"argv":d["argv"],"source_sha256":d["before"]["source_sha256"],"started_at_utc":d["started_at_utc"],"finished_at_utc":d["finished_at_utc"]})
for name in subprocess.run(["git","ls-files","src","tests","pyproject.toml","AGENTS.md"],capture_output=True,text=True,check=True).stdout.splitlines():
    assert (root/name).read_bytes()==subprocess.run(["git","show","HEAD:"+name],capture_output=True,check=True).stdout,name
planning=json.loads((root/"reports/T0006/planning-final-check.json").read_text())
for name in ("reports/T0006/record_check.py","reports/T0006/.gitignore"):
    assert hashlib.sha256((root/name).read_bytes()).hexdigest()==planning["file_sha256"][name]
report={"input_sha256":hashes,"history_sha256":history,"pi_r2_records":records,"previous_history_changes":old_changes,"old_provenance_prefix_preserved":True,"previous_review_artifacts_unchanged":True}
(out/"audit.json").write_text(json.dumps(report,ensure_ascii=False,indent=2)+"\n")
print("PASS frozen product/test hashes, original evidence, append-only provenance, recorder and prior tracked inputs")
print("R2 recorded RUNs:",len(records),"Historical files frozen:",len(history))
for r in records: print(r["run"],"exit=",r["exit_code"],"elapsed_s=",r["elapsed_s"])
